// Pinball NFT · Three.js
// Generated by WebARKit Studio from its node graph (Export → Source code, Three.js).
// Each part below is one node of the graph, in the order the graph runs them: "// <node id> (<node type>)".

import * as THREE from 'three';
import { createNFTTrackerWorker } from '@webarkit/jsartoolkit-nft/client';
import { getProcessGeometry, toFrameGeometry } from '@webarkit/camera-view';

const stage = document.querySelector('#app');

// ---------------------------------------------------------------- setup, once

// camera (source.camera)
// The device camera, in a playing <video>.
const camera_stream = await navigator.mediaDevices.getUserMedia({"audio":false,"video":{"facingMode":"environment","width":{"ideal":640},"height":{"ideal":480}}});
const camera = document.createElement('video');
camera.playsInline = true;
camera.muted = true;
camera.srcObject = camera_stream;
await camera.play();

// camparams (jsartoolkitNFT.cameraParams)
// The camera's calibration file.
const camparams = "data/camera_para.dat";

// dataset (jsartoolkitNFT.dataset)
// An NFT dataset: the URL prefix of its .fset, .fset3 and .iset files.
const dataset = {"url":"data/DataNFT/pinball","name":"pinball"};

// settings (jsartoolkitNFT.settings)
// Tracker settings, as the tracker's configure() takes them.
const settings = {"continuousDetection":true,"detectionInterval":300,"logLevel":2,"near":10,"far":10000,"lostTimeout":200,"ar2":{"trackingThresh":5,"simThresh":0.5,"searchFeatureNum":16,"templateSize1":6,"templateSize2":6,"searchSize":0}};

// filter (filter.oneEuro)
// One Euro filter settings: smoothing for the tracked poses.
const filter = {"kind":"oneEuro","minCutOff":0.0001,"beta":0.01,"warmUp":5};

// renderer (three.renderer)
// Transparent: the camera video shows through.
const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });

// controller (jsartoolkitNFT.controller)
// The tracker processes a copy of the video letterboxed into a 4:3 frame of about 320 px (@webarkit/camera-view's rule).
const controller_geometry = toFrameGeometry(camera.videoWidth, camera.videoHeight, getProcessGeometry(camera.videoWidth, camera.videoHeight, false, true));
const controller_canvas = document.createElement('canvas');
controller_canvas.width = controller_geometry.frameWidth;
controller_canvas.height = controller_geometry.frameHeight;
const controller_context = controller_canvas.getContext('2d', { willReadFrequently: true });

// The jsartoolkitNFT tracker, in its own worker (the "simd" build): scripts/copy-jsartoolkit-nft.mjs copies its file into public/jsartoolkit-nft/.
const controller_tracker = await createNFTTrackerWorker(
  {
    width: controller_geometry.frameWidth,
    height: controller_geometry.frameHeight,
    cameraParam: camparams,
    filter: { type: 'oneEuro', minCutOff: filter.minCutOff, beta: filter.beta, warmUp: filter.warmUp },
    ...settings,
  },
  { build: "simd", workerBase: new URL("jsartoolkit-nft/", document.baseURI) },
);
const controller_loads = await controller_tracker.addNFTTargets([dataset].map((d) => d.url));
for (const load of controller_loads) {
  if (load.status === 'error') throw new Error(`cannot load NFT dataset ${load.url} (${load.reason}): ${load.message}`);
}
// One entry per dataset, updated by every tracking result: found, its pose (column-major, millimetres) and its size.
const controller_indexOf = new Map(controller_loads.map((load, index) => [load.info.id, index]));
const controller_markers = controller_loads.map(({ info }, index) => ({
  index,
  name: [dataset][index].name,
  found: false,
  pose: null,
  info: { id: info.id, width: info.widthPx, height: info.heightPx, dpi: info.dpi, widthMM: info.widthMm, heightMM: info.heightMm },
}));
// The lens mapped back onto the video (the letterbox undone).
const controller_projection = Array.from(controller_tracker.projectionFor({ width: camera.videoWidth, height: camera.videoHeight }, controller_geometry));
const controller_stats = { trackingFps: 0, processMs: 0, latencyMs: 0, frames: 0, windowStart: performance.now(), windowFrames: 0 };
let controller_busy = false;

// scene (scene.scene)
const scene = new THREE.Scene();

// arcamera (scene.arCamera)
// At the origin, looking down -Z, with the tracker's projection: the camera the marker poses are relative to.
const arcamera = new THREE.Camera();
arcamera.matrixAutoUpdate = false;
arcamera.projectionMatrix.fromArray(controller_projection);
arcamera.projectionMatrixInverse.copy(arcamera.projectionMatrix).invert();

// markers (debug.inspector)
// The Inspector shows a value inside the studio only: this app has nothing to do for it.

// stats (debug.stats)
// Tracking stats, in a box over the AR view (added once the view exists).
const stats = document.createElement('div');
stats.style.cssText = 'position:absolute;left:8px;bottom:8px;padding:4px 6px;background:rgb(0 0 0 / .55);color:#7fffd4;font:11px/1.35 monospace;white-space:pre;border-radius:4px;pointer-events:none';
let stats_frames = 0;
let stats_start = performance.now();
let stats_fps = 0;

// select_pinball (tracking.selectMarker)
// The marker "pinball": its pose, found and size, kept current by the tracker.
const select_pinball = controller_markers.find((marker) => marker.name === "pinball") ?? null;
if (!select_pinball) console.warn(`no marker "pinball" (markers: ${controller_markers.map((marker) => marker.name).join(', ')}): nothing follows it`);

// keylight (scene.light)
// Directional: its target is its child, so the direction follows the light (and any anchor it is on).
const keylight = new THREE.DirectionalLight("#ffffff", 2.5);
keylight.position.set(200, -300, 1000);
keylight.add(keylight.target);
keylight.target.position.set(-200, 300, -1000);
scene.add(keylight); // camera space, until an anchor takes it

// filllight (scene.light)
const filllight = new THREE.AmbientLight("#ffffff", 0.6);
scene.add(filllight); // camera space, until an anchor takes it

// prim_pinball (scene.primitive)
const prim_pinball = new THREE.Mesh(new THREE.TorusKnotGeometry(80 / 3, 80 / 10, 100, 16), new THREE.MeshStandardMaterial({ color: "#ff0055" }));
prim_pinball.position.set(0, 0, 0 + 80 / 2); // resting on the marker: lifted by half its size
prim_pinball.rotation.set(0, 0, 0, 'XYZ');

// anchor_pinball (scene.anchor)
// Follows the marker: hidden until it is found.
const anchor_pinball = new THREE.Group();
anchor_pinball.matrixAutoUpdate = false;
anchor_pinball.visible = false;
const anchor_pinball_content = new THREE.Group();
anchor_pinball.add(anchor_pinball_content);
if (select_pinball?.info) anchor_pinball_content.position.set(select_pinball?.info.widthMM / 2, select_pinball?.info.heightMM / 2, 0); // the marker's centre
anchor_pinball_content.add(prim_pinball, keylight);

// view (output.arView)
// The camera video, and the renderer's canvas over it, in a box with the video's aspect.
const view = document.createElement('div');
view.className = 'ar-view';
view.style.cssText = `position:relative;width:100%;aspect-ratio:${camera.videoWidth}/${camera.videoHeight};overflow:hidden;background:#000`;
camera.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;object-fit:fill';
renderer.domElement.style.cssText = 'position:absolute;inset:0;width:100%;height:100%';
renderer.setSize(camera.videoWidth * devicePixelRatio, camera.videoHeight * devicePixelRatio, false);
view.append(camera, renderer.domElement);
const view_fps = document.createElement('div');
view_fps.style.cssText = 'position:absolute;top:6px;left:8px;font:12px monospace;color:#0f0;text-shadow:0 0 2px #000';
view.append(view_fps);
let view_fps_frames = 0;
let view_fps_time = 0;
stage.append(view);
scene.add(anchor_pinball);

// ---------------------------------------------------------------- every frame

let last = null;
function frame(time) {
  const delta = last === null ? 0 : time - last; // milliseconds
  last = time;

  // controller (jsartoolkitNFT.controller)
  // One frame at a time: the next is sent when the tracker has answered.
  if (!controller_busy) {
    const { frameWidth, frameHeight, x, y, width, height } = controller_geometry;
    controller_context.fillStyle = 'black';
    controller_context.fillRect(0, 0, frameWidth, frameHeight);
    controller_context.drawImage(camera, 0, 0, camera.videoWidth, camera.videoHeight, x, y, width, height);
    const image = controller_context.getImageData(0, 0, frameWidth, frameHeight);
    const sentAt = performance.now();
    controller_busy = true;
    controller_tracker
      .process(image, sentAt)
      .then((result) => {
        if (result.skipped) return;
        for (const marker of controller_markers) Object.assign(marker, { found: false, pose: null });
        for (const target of result.targets) {
          const marker = controller_markers[controller_indexOf.get(target.id)];
          if (marker && target.pose) Object.assign(marker, { found: true, pose: Array.from(target.pose) });
        }
        const now = performance.now();
        controller_stats.windowFrames++;
        if (now - controller_stats.windowStart >= 1000) {
          controller_stats.trackingFps = (controller_stats.windowFrames * 1000) / (now - controller_stats.windowStart);
          controller_stats.windowStart = now;
          controller_stats.windowFrames = 0;
        }
        Object.assign(controller_stats, { processMs: result.processMs, latencyMs: now - sentAt, frames: controller_stats.frames + 1 });
      })
      .catch((err) => console.error(err)) // a failed frame does not stop tracking
      .finally(() => (controller_busy = false));
  }

  // stats (debug.stats)
  stats_frames++;
  if (time - stats_start >= 500) {
    stats_fps = (stats_frames * 1000) / (time - stats_start);
    stats_frames = 0;
    stats_start = time;
    if (!stats.isConnected) document.querySelector('.ar-view')?.append(stats);
    stats.textContent = [
      `render  ${stats_fps.toFixed(0)} fps`,
      `track   ${controller_stats.trackingFps.toFixed(1)} fps`,
      `process ${controller_stats.processMs.toFixed(1)} ms`,
      `latency ${controller_stats.latencyMs.toFixed(1)} ms`,
      `frames  ${controller_stats.frames}`,
    ].join('\n');
  }

  // prim_pinball (scene.primitive)
  prim_pinball.rotation.z += delta * 0.0005; // spins about its own Z axis

  // anchor_pinball (scene.anchor)
  anchor_pinball.visible = (select_pinball?.found ?? false) && (select_pinball?.pose ?? null) !== null;
  if ((select_pinball?.pose ?? null)) anchor_pinball.matrix.fromArray((select_pinball?.pose ?? null));

  // view (output.arView)
  renderer.render(scene, arcamera);
  view_fps_frames++;
  view_fps_time += delta;
  if (view_fps_time >= 500) {
    view_fps.textContent = `${Math.round((view_fps_frames * 1000) / view_fps_time)} fps`;
    view_fps_frames = 0;
    view_fps_time = 0;
  }

  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
